function boonCard(boon){const remaining=Math.max(0,Number(boon.uses)||0-(Number(boon.used)||0));const limited=boon.useType==="limited";const left=Math.max(0,(Number(boon.uses)||0)-(Number(boon.used)||0));return `<article class="boon-item"><div class="boon-top"><strong>${esc(boon.name)}</strong><span class="boon-type">${limited?`${left}/${Number(boon.uses)||1} uses left`:"Permanent"}</span></div>${boon.description?`<p class="boon-description">${esc(boon.description)}</p>`:""}<div class="boon-footer"><span>${esc(boon.source||"Source not recorded")}${limited&&boon.resetCondition?` · resets ${esc(boon.resetCondition)}`:""}</span>${limited?`<span class="boon-actions"><button class="small-button" data-reset-boon="${esc(boon.id)}">Reset</button><button class="small-button" data-use-boon="${esc(boon.id)}" ${left<=0?"disabled":""}>Use</button></span>`:""}</div></article>`;}
function renderChronicles(){const rows=[...state.chronicles].sort((a,b)=>(b.datePlayed||"").localeCompare(a.datePlayed||""));app.innerHTML=`<div class="page-intro"><div><p class="eyebrow">PFS 2E · RECORDS</p><h1>Chronicle archive</h1><p>Each confirmed sheet remains attached to its reward entry.</p></div><button class="button button-primary" id="new-chronicle">＋ Record chronicle</button></div><div class="storage-callout"><span>●</span><span><b>${cloudUser?"Private cloud sync":"Files stay on this device"}:</b> ${cloudUser?"Chronicle scans and portraits use private Supabase storage when configured, then download to this browser when opened.":"Ledger data syncs after sign-in; chronicle scans and portraits stay in this browser until you sign in."}</span></div><section class="panel"><div class="panel-title"><h2>All chronicles</h2><span>${rows.length} records</span></div><div class="record-list">${rows.length?rows.map(row=>{const c=state.characters.find(x=>x.id===row.characterId);return `<div class="record-item"><span class="record-icon">▤</span><div class="record-copy"><strong>${esc(row.title||"Untitled chronicle")}</strong><span>${esc(c?.name||"Character removed")} · ${fmtDate(row.datePlayed)} · ${esc(chronicleTypeName(row.sheetType))}</span><button class="link-button" data-chronicle="${esc(row.id)}" data-attachment="${esc(row.fileKey||"")}" data-filename="${esc(row.fileName||"")}">${row.fileKey?"Open sheet":"Attach scan"}</button></div><div class="record-delta">+${Number(row.xpEarned)||0} XP<br>${money((Number(row.gpGained)||0)-(Number(row.gpSpent)||0))}</div></div>`}).join(""):`<div class="list-empty">Confirmed chronicles will appear here.</div>`}</div></section>`;document.querySelector("#new-chronicle").addEventListener("click",()=>openChronicleDialog());document.querySelectorAll("[data-chronicle]").forEach(button=>button.addEventListener("click",()=>{const row=state.chronicles.find(item=>item.id===button.dataset.chronicle);if(row?.fileKey)openAttachment(row.fileKey,row.fileName);else if(row)openChronicleDialog(row.characterId,"",row.id);}));}
function openCharacter(id){selectedCharacterId=id;currentView="detail";render();}
function structuredReputation(data){const changes={};for(let index=1;index<=3;index++){const faction=String(data.get(`repFaction${index}`)||"");const amount=Number(data.get(`repAmount${index}`))||0;if(faction&&amount)changes[faction]=amount;}return changes;}
function legacyReputation(row){if(row.reputationChanges)return Object.entries(row.reputationChanges);return String(row.reputation||"").split(/[;\n]+/).map(parseRep).filter(item=>item.name).map(item=>[item.name,item.amount]);}
function syncRepFactionOptions(){const selects=[...document.querySelectorAll(".rep-faction")];for(const select of selects){const elsewhere=new Set(selects.filter(other=>other!==select).map(other=>other.value).filter(Boolean));for(const option of select.options)option.disabled=Boolean(option.value&&elsewhere.has(option.value));}}
document.querySelectorAll(".rep-faction").forEach(select=>select.addEventListener("change",syncRepFactionOptions));
function openChronicleDialog(characterId,historyId="",targetId="",editId=""){selectedCharacterId=characterId||selectedCharacterId;const form=document.querySelector("#chronicle-form");form.reset();syncRepFactionOptions();form.elements.targetChronicleId.value=targetId;form.elements.editChronicleId.value=editId;selectedChronicleFile=null;document.querySelector("#chronicle-review").hidden=true;document.querySelector("#scan-status").textContent="Upload a sheet to start. You can also enter everything by hand.";document.querySelector("#scan-status").className="scan-status";document.querySelector("#save-chronicle").disabled=false;const select=form.elements.characterId;select.innerHTML=state.characters.map(c=>`<option value="${esc(c.id)}" ${c.id===selectedCharacterId?"selected":""}>${esc(c.name)}</option>`).join("");if(!state.characters.length){alert("Add a character before recording a chronicle.");return;}if(historyId){const row=state.sessionHistory.find(item=>item.id===historyId);if(row){form.elements.historyEntryId.value=row.id;form.elements.title.value=row.title;form.elements.datePlayed.value=row.date;form.elements.event.value=row.event||"";form.elements.role.value=/gm|game master/i.test(row.role||"")?"gm":"player";const code=(row.title.match(/(?:#|PFS(?:\(2ed\))?\s*)(\d{1,2}[-–]\d{1,3})/i)||[])[1];if(code)form.elements.scenarioCode.value=code.replace("–","-");}}if(editId){const row=state.chronicles.find(item=>item.id===editId);if(row){form.elements.title.value=row.title||"";form.elements.sheetType.value=row.sheetType||"scenario";form.elements.scenarioCode.value=row.scenarioCode||"";form.elements.chronicleCode.value=row.chronicleCode||"";form.elements.datePlayed.value=row.datePlayed||"";form.elements.event.value=row.event||"";form.elements.role.value=row.role==="gm"?"gm":"player";form.elements.xpEarned.value=Number(row.xpEarned)||0;form.elements.gpGained.value=Number(row.gpGained)||0;form.elements.gpSpent.value=Number(row.gpSpent)||0;form.elements.gpAdjustment.value=Number(row.gpAdjustment)||0;legacyReputation(row).slice(0,3).forEach(([name,amount],index)=>{form.elements[`repFaction${index+1}`].value=PFS2_FACTIONS.includes(name)?name:"";form.elements[`repAmount${index+1}`].value=amount;});syncRepFactionOptions();form.elements.notes.value=row.notes||"";document.querySelector("#chronicle-review").hidden=false;document.querySelector("#scan-kind").textContent=chronicleTypeName(row.sheetType);document.querySelector("#scan-status").textContent="Edit the chronicle values, then save to update this ledger entry.";}}chronicleDialog.showModal();}
function openBoonDialog(characterId){const form=document.querySelector("#boon-form");form.reset();form.elements.characterId.value=characterId;form.elements.uses.value=1;boonDialog.showModal();}
function setCharacterBaseline(id){const character=state.characters.find(row=>row.id===id);if(!character)return;const xp=prompt(`Current total XP for ${character.name}:`,String(character.startingXp||0));if(xp===null)return;const gp=prompt(`Current gold in gp for ${character.name}:`,String(character.startingGp||0));if(gp===null)return;character.startingXp=Math.max(0,Number(xp)||0);character.startingGp=Number(gp)||0;character.baselineUnknown=false;saveState();render();}
async function importPaizoHistory(event){
  const file=event.target.files?.[0];if(!file)return;
  try{const data=JSON.parse(await file.text());
    if(data.format==="society-ledger-migration-v1"){
      let addedCharacters=0,addedChronicles=0,addedSessions=0;
      for(const source of data.characters){const importedOrganizedPlayId=String(source.organizedPlayId||String(source.paizoRef||"").split("-")[0]||"");
        let character=state.characters.find(c=>c.paizoRef===source.paizoRef||(c.characterNumber===source.characterNumber&&c.organizedPlayId===importedOrganizedPlayId));
        if(!character){character={id:makeId(),name:source.displayName,organizedPlayId:importedOrganizedPlayId,characterNumber:source.characterNumber,paizoRef:source.paizoRef,portraitKey:"",createdAt:new Date().toISOString()};state.characters.push(character);addedCharacters++;}
        Object.assign(character,{name:source.displayName,organizedPlayId:importedOrganizedPlayId,characterNumber:source.characterNumber,paizoRef:source.paizoRef,faction:source.current.primaryFaction||character.faction||"",baselineUnknown:false});
        if(!character.importedGoogleLedger){
          character.startingXp=(Number(source.current.xp)||0)-source.ledger.reduce((sum,row)=>sum+(Number(row.xpEarned)||0),0);character.startingGp=(Number(source.current.gp)||0)-source.ledger.reduce((sum,row)=>sum+(Number(row.gpGained)||0)-(Number(row.gpSpent)||0),0);
          for(const item of source.ledger){if(state.chronicles.some(row=>row.googleLedgerId===item.id))continue;
            const note=item.purchaseNote?"Gear note: "+item.purchaseNote+(item.referenceCost?" (reference cost "+item.referenceCost+" gp; not deducted)":"")+"; imported as an unconfirmed purchase note.":"";
            state.chronicles.push({id:makeId(),googleLedgerId:item.id,characterId:character.id,title:item.title,sheetType:"scenario",datePlayed:"",xpEarned:Number(item.xpEarned)||0,gpGained:Number(item.gpGained)||0,gpSpent:Number(item.gpSpent)||0,reputationChanges:item.repByFaction||{},role:normalizeRole(source.paizoSessions?.find(session=>session.matchedLedgerId===item.id)?.role),notes:note,fileKey:"",fileName:"",confirmed:true,createdAt:new Date().toISOString(),source:"Google Sheet"});addedChronicles++;
          }const ledgerRep={};for(const row of source.ledger)for(const [name,value] of Object.entries(row.repByFaction||{}))ledgerRep[name]=(ledgerRep[name]||0)+(Number(value)||0);character.startingReputation={};for(const [name,value] of Object.entries(source.current.repByFaction||{})){const delta=(Number(value)||0)-(ledgerRep[name]||0);if(delta)character.startingReputation[name]=delta;}for(const [label,name] of [["Mentor boon",source.current.mentorBoon],["Hero Point boon",source.current.heroPointBoon]])if(name&&name!=="None"&&!state.boons.some(b=>b.characterId===character.id&&b.name===name))state.boons.push({id:makeId(),characterId:character.id,name,source:"Google Sheet · "+label,description:"",useType:"permanent",uses:0,used:0,resetCondition:""});character.importedGoogleLedger=true;character.importedCurrent=source.current;
        }
        character.startingGp=Number(source.ledger[0]?.startingGold)||0;
        for(let i=0;i<source.ledger.length;i++){const item=source.ledger[i],previous=source.ledger[i-1];const adjustment=previous?(Number(item.startingGold)||0)-(Number(previous.goldRemaining)||0):0;const importedChronicle=state.chronicles.find(row=>row.googleLedgerId===item.id);if(importedChronicle)importedChronicle.gpAdjustment=adjustment;if(item.purchaseNote){const purchaseId="google-purchase:"+item.id;const existingNote=state.purchases.find(row=>row.id===purchaseId);if(existingNote){existingNote.chronicleId=importedChronicle?.id||"";existingNote.itemized=false;}else state.purchases.push({id:purchaseId,characterId:character.id,chronicleId:importedChronicle?.id||"",item:item.purchaseNote,cost:Number(item.referenceCost)||0,date:"",notes:"From "+item.title+". Payment status is unclear; reference cost is not deducted from wealth.",source:"Google Sheet",affectsBalance:false,itemized:false});}}
        for(const p of source.paizoSessions||[]){const id="paizo:"+source.paizoRef+":"+p.eventCode+":"+p.session+":"+p.date;let row=state.sessionHistory.find(r=>r.id===id);
          if(!row){row={id,characterId:character.id,date:p.date,role:p.role,title:p.title,event:p.event,eventCode:p.eventCode,session:p.session,gm:p.gm,faction:p.faction,reputation:p.reputation,notes:p.notes,linkedChronicleId:""};state.sessionHistory.push(row);addedSessions++;}
          if(p.matchedLedgerId){const chronicle=state.chronicles.find(r=>r.googleLedgerId===p.matchedLedgerId);if(chronicle){row.linkedChronicleId=chronicle.id;if(p.role)chronicle.role=normalizeRole(p.role);}}
        }
      }
      saveState();alert("Imported "+addedCharacters+" characters, "+addedChronicles+" new ledger chronicles, and "+addedSessions+" new Paizo sessions. Re-import this file to apply updates without duplicates. Review unmatched sessions and attach scans as needed.");render();return;
    }
    if(data.game!=="Pathfinder Society 2e"||!Array.isArray(data.characters))throw new Error("Choose the combined society migration JSON or a PFS2 history JSON.");
    let addedCharacters=0,addedSessions=0;
    for(const source of data.characters){const parts=String(source.paizoRef||"").split("-");let character=state.characters.find(c=>c.paizoRef===source.paizoRef||c.name.toLowerCase()===source.name.toLowerCase());
      if(!character){character={id:makeId(),name:source.name,organizedPlayId:parts.length>1?parts[0]:"",characterNumber:parts.length>1?parts.slice(1).join("-"):"",paizoRef:source.paizoRef,faction:source.sessions.at(-1)?.faction||"",startingXp:0,startingGp:0,baselineUnknown:true,portraitKey:"",createdAt:new Date().toISOString()};state.characters.push(character);addedCharacters++;}
      for(const session of source.sessions){const id="paizo:"+source.paizoRef+":"+session.eventCode+":"+session.session+":"+session.date;if(state.sessionHistory.some(row=>row.id===id))continue;state.sessionHistory.push({id,characterId:character.id,date:session.date,role:session.role,title:session.title,event:session.event,eventCode:session.eventCode,session:session.session,gm:session.gm,faction:session.faction,reputation:session.reputation,notes:session.notes,linkedChronicleId:""});addedSessions++;}
    }saveState();alert("Imported "+addedCharacters+" characters and "+addedSessions+" session checklist entries. Starting XP and gold are not included.");render();
  }catch(error){alert(error.message||"Could not import that file.");}finally{event.target.value="";}
}
function setStatus(message,type=""){const el=document.querySelector("#scan-status");el.textContent=message;el.className=`scan-status ${type}`;}
function normalizeText(text){return String(text||"").replace(/\r/g,"\n").replace(/[\t ]+/g," ").replace(/\n{3,}/g,"\n\n").trim();}
async function extractPdfText(file){const pdfjs=await import("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs");pdfjs.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs";const buffer=await file.arrayBuffer();const pdf=await pdfjs.getDocument({data:buffer}).promise;let text="";for(let pageNo=1;pageNo<=Math.min(pdf.numPages,6);pageNo++){const page=await pdf.getPage(pageNo);const content=await page.getTextContent();text+=content.items.map(item=>item.str).join(" ")+"\n";}if(text.replace(/\s/g,"").length<40){for(let pageNo=1;pageNo<=Math.min(pdf.numPages,2);pageNo++){const page=await pdf.getPage(pageNo);const viewport=page.getViewport({scale:2});const canvas=document.createElement("canvas");canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext("2d"),viewport}).promise;text+=await ocrBlob(await new Promise(resolve=>canvas.toBlob(resolve,"image/png")));}}return text;}
async function ocrBlob(blob){if(!window.Tesseract)throw new Error("Photo OCR could not load. Check your internet connection or enter the fields by hand.");const result=await window.Tesseract.recognize(blob,"eng",{logger:message=>{if(message.status==="recognizing text")setStatus(`Reading the sheet… ${Math.round((message.progress||0)*100)}%`);}});return result.data.text||"";}
function suggestTitle(text,fileName){const line=(text.match(/(?:Pathfinder Society Scenario|Pathfinder Adventure|Pathfinder Society Quest)[^\n]{0,130}/i)||[])[0];if(line)return line.replace(/\s+/g," ").trim().slice(0,110);return fileName.replace(/\.[^.]+$/,"").replace(/\s*[-–]\s*chronicle.*$/i,"");}
function suggestCode(text){const scenario=(text.match(/(?:Scenario|Quest)\s*#?\s*(\d{1,2}[-–]\d{1,3})/i)||[])[1];const chronicle=(text.match(/Chronicle Code\s*:?\s*([A-Z0-9]{3,8})/i)||[])[1];return {scenarioCode:scenario||"",chronicleCode:chronicle||""};}
function detectSheetType(text){if(/Starting XP|Starting GP|Total XP|GP Spent/i.test(text))return"scenario";if(/Items Sold|Items Bought|Downtime|Reputation Gained/i.test(text))return"adventure";if(/Achievement Point Reward|grants access|This Chronicle Sheet Grants Access/i.test(text))return"boon";return"scenario";}
async function processChronicle(file){selectedChronicleFile=file;document.querySelector("#chronicle-review").hidden=false;document.querySelector("#save-chronicle").disabled=true;setStatus(`Reading ${file.name}…`);let text="";try{text=file.type==="application/pdf"?await extractPdfText(file):await ocrBlob(file);text=normalizeText(text);document.querySelector("#ocr-text").textContent=text||"No readable text was found. Enter details below by hand.";const form=document.querySelector("#chronicle-form");const code=suggestCode(text);form.elements.title.value=suggestTitle(text,file.name);form.elements.scenarioCode.value=code.scenarioCode;form.elements.chronicleCode.value=code.chronicleCode;const type=detectSheetType(text);form.elements.sheetType.value=type;document.querySelector("#scan-kind").textContent=chronicleTypeName(type);document.querySelector("#scan-kind").classList.toggle("scan-kind-conflict",!text);setStatus(text?`Text read from ${file.name}. Review the fields below and enter any rewards the reader did not identify.`:`No text was recognized from ${file.name}. You can still complete the form by hand.`,text?"ready":"error");}catch(error){document.querySelector("#ocr-text").textContent=String(error.message||error);setStatus(`${error.message||"Could not read the file."} You can still enter the chronicle manually.`,"error");}finally{document.querySelector("#save-chronicle").disabled=false;}}
function storeBoonsFromText(characterId,rawNames,source){for(const name of rawNames.split(/\n+/).map(s=>s.trim()).filter(Boolean)){state.boons.push({id:makeId(),characterId,name,source:source||"Chronicle sheet",description:"",useType:"permanent",uses:0,used:0,resetCondition:""});}}
function parseRepInput(value){const result=parseRep(value);return result.name?result:null;}
document.querySelector("#character-form").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget;const data=new FormData(form);const character={id:makeId(),name:String(data.get("name")).trim(),organizedPlayId:String(data.get("organizedPlayId")||"").trim(),characterNumber:String(data.get("characterNumber")||"").trim(),faction:String(data.get("faction")||"").trim(),startingXp:Number(data.get("xp"))||0,startingGp:Number(data.get("gp"))||0,portraitKey:"",createdAt:new Date().toISOString()};const portrait=data.get("portrait");if(portrait instanceof File&&portrait.size){character.portraitKey=`portrait:${character.id}`;await filePut(character.portraitKey,portrait);}state.characters.push(character);saveState();characterDialog.close();form.reset();selectedCharacterId=character.id;currentView="detail";render();});
document.querySelector("#chronicle-file").addEventListener("change",event=>{const file=event.target.files?.[0];if(file)processChronicle(file);});
document.querySelector("#chronicle-form").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget;const data=new FormData(form);const characterId=String(data.get("characterId"));const title=String(data.get("title")||"").trim();if(!characterId||!title)return;const reputationChanges=structuredReputation(data);const fileKey=selectedChronicleFile?`chronicle:${makeId()}`:"";if(selectedChronicleFile)await filePut(fileKey,selectedChronicleFile);const targetId=String(data.get("targetChronicleId")||"");const existing=targetId?state.chronicles.find(item=>item.id===targetId):null;if(existing&&selectedChronicleFile){existing.fileKey=fileKey;existing.fileName=selectedChronicleFile.name;existing.mimeType=selectedChronicleFile.type;const linkedSession=state.sessionHistory.find(item=>item.id===String(data.get("historyEntryId")||""));if(linkedSession)linkedSession.linkedChronicleId=existing.id;saveState();chronicleDialog.close();selectedChronicleFile=null;form.reset();selectedCharacterId=characterId;currentView="detail";render();return;}const editId=String(data.get("editChronicleId")||"");const edited=editId?state.chronicles.find(item=>item.id===editId):null;if(edited){Object.assign(edited,{sheetType:String(data.get("sheetType")),title,scenarioCode:String(data.get("scenarioCode")||"").trim(),chronicleCode:String(data.get("chronicleCode")||"").trim(),datePlayed:String(data.get("datePlayed")||""),event:String(data.get("event")||"").trim(),role:String(data.get("role")||"player"),xpEarned:Number(data.get("xpEarned"))||0,gpGained:Number(data.get("gpGained"))||0,gpSpent:Number(data.get("gpSpent"))||0,gpAdjustment:Number(data.get("gpAdjustment"))||0,reputationChanges,notes:String(data.get("notes")||"").trim()});delete edited.reputation;if(selectedChronicleFile){edited.fileKey=fileKey;edited.fileName=selectedChronicleFile.name;edited.mimeType=selectedChronicleFile.type;}storeBoonsFromText(characterId,String(data.get("boons")||""),edited.title);saveState();chronicleDialog.close();selectedChronicleFile=null;form.reset();selectedCharacterId=characterId;currentView="detail";render();return;}const row={id:makeId(),characterId,sheetType:String(data.get("sheetType")),title,scenarioCode:String(data.get("scenarioCode")||"").trim(),chronicleCode:String(data.get("chronicleCode")||"").trim(),datePlayed:String(data.get("datePlayed")||""),event:String(data.get("event")||"").trim(),role:String(data.get("role")||"player"),xpEarned:Number(data.get("xpEarned"))||0,gpGained:Number(data.get("gpGained"))||0,gpSpent:Number(data.get("gpSpent"))||0,gpAdjustment:Number(data.get("gpAdjustment"))||0,reputationChanges,notes:String(data.get("notes")||"").trim(),fileKey,fileName:selectedChronicleFile?.name||"",mimeType:selectedChronicleFile?.type||"",confirmed:true,createdAt:new Date().toISOString()};state.chronicles.push(row);const historyId=String(data.get("historyEntryId")||"");const session=state.sessionHistory.find(item=>item.id===historyId);if(session)session.linkedChronicleId=row.id;const firstFaction=Object.keys(reputationChanges)[0];if(firstFaction){const character=state.characters.find(c=>c.id===characterId);if(character&&!character.faction)character.faction=firstFaction;}storeBoonsFromText(characterId,String(data.get("boons")||""),row.title);saveState();chronicleDialog.close();selectedChronicleFile=null;form.reset();selectedCharacterId=characterId;currentView="detail";render();});
document.querySelector("#boon-form").addEventListener("submit",event=>{event.preventDefault();const data=new FormData(event.currentTarget);const limited=data.get("useType")==="limited";state.boons.push({id:makeId(),characterId:String(data.get("characterId")),name:String(data.get("name")).trim(),source:String(data.get("source")||"").trim(),description:String(data.get("description")||"").trim(),useType:limited?"limited":"permanent",uses:limited?Math.max(1,Number(data.get("uses"))||1):0,used:0,resetCondition:limited?String(data.get("resetCondition")||"manual").trim():""});saveState();boonDialog.close();const characterId=String(data.get("characterId"));event.currentTarget.reset();selectedCharacterId=characterId;currentView="detail";render();});
function openPurchaseDialog(characterId,purchaseId=""){const form=document.querySelector("#purchase-form");form.reset();const row=state.purchases.find(item=>item.id===purchaseId);form.elements.characterId.value=characterId;form.elements.purchaseId.value=purchaseId;form.elements.chronicleId.innerHTML=`<option value="">Between chronicles / unassigned</option>`+state.chronicles.filter(c=>c.characterId===characterId).sort((a,b)=>(b.datePlayed||"").localeCompare(a.datePlayed||"")).map(c=>`<option value="${esc(c.id)}">${esc(c.title)}</option>`).join("");if(row){form.elements.item.value=row.item||"";form.elements.cost.value=Number(row.cost)||0;form.elements.date.value=row.date||"";form.elements.location.value=row.location||"";form.elements.chronicleId.value=row.chronicleId||"";form.elements.notes.value=row.notes||"";form.elements.itemized.checked=Boolean(row.itemized);form.elements.affectsBalance.checked=row.affectsBalance!==false;form.querySelector("h2").textContent="Edit purchase or gear note";form.querySelector("button[type=submit]").textContent="Save changes";}else{form.elements.affectsBalance.checked=true;form.querySelector("h2").textContent="Record a purchase";form.querySelector("button[type=submit]").textContent="Save purchase";}document.querySelector("#purchase-dialog").showModal();}
document.querySelector("#purchase-form").addEventListener("submit",event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),characterId=String(data.get("characterId")),id=String(data.get("purchaseId")||"");const chronicleId=String(data.get("chronicleId")||""),itemized=Boolean(data.get("itemized"))&&Boolean(chronicleId);const values={characterId,item:String(data.get("item")).trim(),cost:Number(data.get("cost"))||0,date:String(data.get("date")||""),location:String(data.get("location")||"").trim(),chronicleId,notes:String(data.get("notes")||"").trim(),itemized,affectsBalance:itemized?false:Boolean(data.get("affectsBalance"))};const row=state.purchases.find(item=>item.id===id);if(row)Object.assign(row,values);else state.purchases.push({id:makeId(),...values,createdAt:new Date().toISOString()});saveState();document.querySelector("#purchase-dialog").close();form.reset();selectedCharacterId=characterId;currentView="detail";render();});
function useBoon(id){const boon=state.boons.find(b=>b.id===id);if(!boon||boon.useType!=="limited")return;const left=Math.max(0,(Number(boon.uses)||0)-(Number(boon.used)||0));if(left<=0)return;boon.used=(Number(boon.used)||0)+1;boon.usageLog=[...(boon.usageLog||[]),new Date().toISOString()];saveState();render();}
function resetBoon(id){const boon=state.boons.find(b=>b.id===id);if(!boon||boon.useType!=="limited")return;boon.used=0;boon.usageLog=[];saveState();render();}
async function openAttachment(key,name){const blob=await fileGet(key);if(!blob){alert("The attachment is not available in this browser.");return;}const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.target="_blank";link.rel="noopener";link.download=name||"chronicle";link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
document.querySelector("#account-button").addEventListener("click",async()=>{if(cloudUser){if(confirm(`Sign out ${cloudUser.email||"of this account"}? Your local browser copy stays here.`)){if(cloudUnsubscribe)cloudUnsubscribe();cloudUnsubscribe=null;await signOut(firebaseAuth);}return;}document.querySelector("#auth-error").hidden=true;document.querySelector("#auth-dialog").showModal();});
document.querySelector("#auth-form").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget,button=event.submitter,errorBox=document.querySelector("#auth-error"),email=String(form.elements.email.value).trim(),password=String(form.elements.password.value);errorBox.hidden=true;try{if(button?.value==="signUp")await createUserWithEmailAndPassword(firebaseAuth,email,password);else await signInWithEmailAndPassword(firebaseAuth,email,password);document.querySelector("#auth-dialog").close();form.reset();}catch(error){errorBox.textContent=error.message||"Authentication failed.";errorBox.hidden=false;}});
