onAuthStateChanged(firebaseAuth,user=>{clearTimeout(cloudWriteTimer);pendingCloudState=null;if(cloudUnsubscribe)cloudUnsubscribe();cloudUnsubscribe=null;cloudUser=user;const button=document.querySelector("#account-button");if(!user){hideCloudConflict();button.textContent="Sign in";setSyncStatus("Local only");return;}button.textContent="Sign out";initializeCloudFor(user);});
